"use client";
import { useRef } from "react";
import {
  useScrollMotion,
  scrollUnits,
  scrollStage,
  type ScrollMotionProps,
  type ScrollItem,
} from "./scroll-shared";
import { scrollRandom, scrollEase, scrollStagger, scrollLerp } from "./scroll-math";
export interface MultiFlipProps extends ScrollMotionProps {
  items: readonly ScrollItem[];
  columns?: number;
  gap?: number;
  stagger?: number;
  rotation?: number;
  pileSpread?: number;
}
export function MultiFlip({
  items,
  columns = 3,
  gap = 16,
  stagger = 0.35,
  rotation = 26,
  pileSpread = 0.2,
  ...props
}: MultiFlipProps) {
  const root = useRef<HTMLDivElement>(null);
  useScrollMotion(
    root,
    props,
    ({ progress: p, width: w, height: h }) => {
      const cols = Math.max(
          1,
          Math.min(items.length || 1, Math.floor(columns), w < 480 ? 2 : columns),
        ),
        rows = Math.ceil(items.length / cols),
        g = Math.min(gap, w * 0.05),
        cw = Math.min(
          (w - g * (cols + 1)) / cols,
          ((h - g * (rows + 1)) / Math.max(1, rows)) * 0.77,
        ),
        ch = cw / 0.77,
        gw = cols * cw + (cols - 1) * g,
        gh = rows * ch + (rows - 1) * g;
      scrollUnits(root.current!).forEach((el, i) => {
        const q = scrollEase(scrollStagger(p, i, items.length, stagger)),
          x = (i % cols) * (cw + g) + (w - gw) / 2,
          y = Math.floor(i / cols) * (ch + g) + (h - gh) / 2;
        el.style.width = `${cw}px`;
        el.style.height = `${ch}px`;
        el.style.transform = `translate(${scrollLerp((w - cw) / 2 + (scrollRandom(i) - 0.5) * w * pileSpread, x, q)}px,${scrollLerp((h - ch) / 2 + (scrollRandom(i, 4) - 0.5) * h * pileSpread, y, q)}px) rotate(${(scrollRandom(i, 7) - 0.5) * rotation * 2 * (1 - q)}deg)`;
      });
    },
    `${items.map((x) => x.id).join(",")}:${columns}:${gap}:${stagger}:${rotation}:${pileSpread}`,
  );
  return (
    <div
      ref={root}
      data-scroll-animation="multi-flip"
      className={props.className}
      style={{ ...scrollStage, ...props.style }}
    >
      {items.map((item) => (
        <div
          data-scroll-unit={item.id}
          key={item.id}
          className={item.className}
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: "24%",
            height: "36%",
            borderRadius: 8,
            overflow: "hidden",
            boxShadow: "0 12px 25px #0002",
            ...item.style,
          }}
        >
          {item.content}
        </div>
      ))}
    </div>
  );
}

// @zeus-internal
export const scrollClamp = (n: number) => (Number.isFinite(n) ? Math.max(0, Math.min(1, n)) : 0);
export const scrollLerp = (a: number, b: number, p: number) => a + (b - a) * scrollClamp(p);
export const scrollRange = (value: number, start: number, end: number) =>
  start === end ? Number(value >= end) : scrollClamp((value - start) / (end - start));
export const scrollEase = (p: number) => {
  const q = scrollClamp(p);
  return q * q * (3 - 2 * q);
};
export const scrollStagger = (p: number, index: number, count: number, spread = 0.4) => {
  const s = Math.min(0.95, Math.max(0, spread));
  return scrollClamp((p - (index / Math.max(1, count - 1)) * s) / (1 - s));
};
export const scrollRandom = (index: number, seed = 1) => {
  const x = Math.sin((index + 1) * 127.1 + seed * 311.7) * 43758.5453;
  return x - Math.floor(x);
};
export interface ScrollFrame {
  x: number;
  y: number;
  width: number;
  height: number;
  rotation?: number;
  radius?: number;
}
export function scrollFrame(
  frames: readonly ScrollFrame[],
  progress: number,
): Required<ScrollFrame> {
  const p = scrollClamp(progress) * Math.max(0, frames.length - 1),
    index = Math.floor(p);
  const a = frames[index] ?? { x: 0, y: 0, width: 100, height: 100 },
    b = frames[Math.min(index + 1, frames.length - 1)] ?? a;
  return {
    x: scrollLerp(a.x, b.x, p - index),
    y: scrollLerp(a.y, b.y, p - index),
    width: scrollLerp(a.width, b.width, p - index),
    height: scrollLerp(a.height, b.height, p - index),
    rotation: scrollLerp(a.rotation ?? 0, b.rotation ?? 0, p - index),
    radius: scrollLerp(a.radius ?? 0, b.radius ?? 0, p - index),
  };
}
/** Color stops accept CSS hex (3/6 digits) or rgb/rgba. Unknown formats hold until the next stop. */
export function scrollMixColor(a: string, b: string, p: number) {
  const parse = (s: string): number[] | null => {
    const hex = s.replace(/^#/, "");
    if (/^[0-9a-f]{3}$/i.test(hex)) return [...hex].map((x) => parseInt(x + x, 16));
    if (/^[0-9a-f]{6}$/i.test(hex)) return [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16));
    const parts = s
      .match(/^rgba?\(([^)]+)\)$/)?.[1]
      ?.match(/[\d.]+/g)
      ?.map(Number);
    return parts && parts.length >= 3 ? parts : null;
  };
  const ca = parse(a),
    cb = parse(b);
  if (!ca || !cb) return p < 1 ? a : b;
  const channels = [0, 1, 2].map((i) => Math.round(scrollLerp(ca[i]!, cb[i]!, p))).join(", ");
  return ca.length > 3 || cb.length > 3
    ? `rgba(${channels}, ${scrollLerp(ca[3] ?? 1, cb[3] ?? 1, p)})`
    : `rgb(${channels})`;
}

