"use client";
import { useEffect, useRef, type CSSProperties, type ReactNode, type RefObject } from "react";
import { scrollClamp, scrollRange } from "./scroll-math";
export interface ScrollMotionProps {
  className?: string;
  style?: CSSProperties;
  /** Override native scroll with normalized 0–1 progress. */
  progress?: number;
  /** Omit to discover the nearest scrolling ancestor, then the document. */
  scrollContainer?: RefObject<HTMLElement | null>;
  /** Track this element's passage through the viewport instead of the animated element. */
  scrollTarget?: RefObject<HTMLElement | null>;
  /** Optional absolute scroll offset range in pixels. */
  range?: readonly [number, number];
  /** Viewport fraction at which the target's top starts / bottom ends its passage. */
  start?: number;
  end?: number;
  /** Response time in seconds; zero follows scroll immediately. */
  scrub?: number;
  onProgress?: (progress: number) => void;
}
export interface ScrollItem {
  id: string;
  content: ReactNode;
  className?: string;
  style?: CSSProperties;
}
export interface ScrollMetrics {
  progress: number;
  raw: number;
  velocity: number;
  offset: number;
  reduced: boolean;
  width: number;
  height: number;
}
export interface ScrollEntranceOptions {
  trigger?: "scroll" | "enter";
  duration?: number;
  delay?: number;
  once?: boolean;
  replayKey?: string | number;
}
export function scrollParent(element: HTMLElement): HTMLElement | null {
  let p = element.parentElement;
  while (p) {
    if (/(auto|scroll)/.test(getComputedStyle(p).overflowY) && p.scrollHeight > p.clientHeight)
      return p;
    p = p.parentElement;
  }
  return null;
}
/** Only the owning instance is scheduled, and frames stop once progress and velocity settle. */
export function useScrollMotion<T extends HTMLElement>(
  root: RefObject<T | null>,
  options: ScrollMotionProps & ScrollEntranceOptions,
  draw: (metrics: ScrollMetrics) => void,
  key = "",
  preserveProgress = false,
  pageProgress = false,
) {
  const latest = useRef({ options, draw });
  latest.current = { options, draw };
  const refresh = useRef<(() => void) | null>(null);
  const {
    scrollContainer,
    scrollTarget,
    range,
    start = 0.9,
    end = 0.1,
    scrub = 0.12,
    trigger = "scroll",
    duration = 1.2,
    delay = 0,
    once = true,
    replayKey,
  } = options;
  useEffect(() => {
    const el = root.current;
    if (!el) return;
    const container = scrollContainer?.current ?? scrollParent(el),
      target = scrollTarget?.current ?? el;
    const media = matchMedia("(prefers-reduced-motion: reduce)");
    let frame = 0,
      disposed = false,
      visible = true,
      previousTime = 0,
      changed = performance.now(),
      velocity = 0,
      p = 0,
      raw = 0,
      offset = container?.scrollTop ?? window.scrollY,
      width = el.clientWidth,
      height = el.clientHeight,
      entered = false,
      entryTime = 0,
      entryDone = false;
    // A replay detaches refs before passive effect cleanup; queued observers can also outlive cleanup.
    const ownsRoot = () => !disposed && root.current === el;
    const readOffset = () => container?.scrollTop ?? window.scrollY;
    const render = () => {
      if (!ownsRoot()) return;
      const reduced = media.matches,
        value = reduced && !preserveProgress ? 1 : scrollClamp(p);
      latest.current.draw({
        progress: value,
        raw,
        velocity: reduced ? 0 : velocity,
        offset,
        reduced,
        width,
        height,
      });
      el.dataset.progress = String(value);
      el.dataset.velocity = String(reduced ? 0 : velocity);
      el.dataset.reduced = String(reduced);
      latest.current.options.onProgress?.(value);
    };
    const tick = (now: number) => {
      frame = 0;
      if (!ownsRoot() || document.hidden || !visible) return;
      const dt = previousTime ? Math.min(64, now - previousTime) : 16;
      previousTime = now;
      if (trigger === "enter" && latest.current.options.progress === undefined && entered) {
        raw = scrollClamp((now - entryTime - delay * 1000) / Math.max(1, duration * 1000));
        entryDone = raw === 1;
      }
      const response =
        media.matches || scrub <= 0 ? 1 : 1 - Math.exp(-dt / Math.max(1, scrub * 1000));
      p += (raw - p) * response;
      if (Math.abs(raw - p) < 0.0001) p = raw;
      if (now - changed > 50) velocity *= Math.exp(-dt / 95);
      if (Math.abs(velocity) < 0.1) velocity = 0;
      render();
      if (!ownsRoot() || media.matches) return;
      if (
        Math.abs(raw - p) > 0.0001 ||
        velocity !== 0 ||
        (trigger === "enter" && entered && !entryDone)
      )
        frame = requestAnimationFrame(tick);
    };
    const schedule = () => {
      if (!frame && ownsRoot() && !document.hidden && visible && !media.matches) {
        previousTime = 0;
        frame = requestAnimationFrame(tick);
      }
    };
    const measure = () => {
      if (!ownsRoot()) return;
      width = el.clientWidth;
      height = el.clientHeight;
      const next = readOffset(),
        now = performance.now(),
        delta = next - offset;
      if (delta !== 0) {
        velocity = Math.max(-12000, Math.min(12000, (delta / Math.max(16, now - changed)) * 1000));
        changed = now;
        offset = next;
      }
      const controlled = latest.current.options.progress;
      if (controlled !== undefined) raw = scrollClamp(controlled);
      else if (trigger === "scroll") {
        if (range) raw = scrollRange(offset, range[0], range[1]);
        else if ((scrollContainer?.current && !scrollTarget?.current) || pageProgress) {
          const max = container
            ? container.scrollHeight - container.clientHeight
            : document.documentElement.scrollHeight - window.innerHeight;
          raw = scrollRange(offset, 0, Math.max(1, max));
        } else {
          const rect = target.getBoundingClientRect(),
            bounds = container?.getBoundingClientRect(),
            vh = container?.clientHeight ?? innerHeight;
          raw = scrollRange(
            vh * start - (rect.top - (bounds?.top ?? 0)),
            0,
            rect.height + vh * (start - end),
          );
        }
      }
      if (media.matches || scrub <= 0 || controlled !== undefined) p = raw;
      render();
      schedule();
    };
    refresh.current = measure;
    const observer =
      typeof IntersectionObserver !== "undefined"
        ? new IntersectionObserver(
            (entries) => {
              if (!ownsRoot()) return;
              visible = entries[0]?.isIntersecting ?? true;
              if (trigger === "enter" && visible && (!entered || (!once && !entryDone))) {
                entered = true;
                entryTime = performance.now();
              }
              if (!visible) {
                cancelAnimationFrame(frame);
                frame = 0;
                if (!once) {
                  entered = false;
                  entryDone = false;
                  raw = 0;
                  p = 0;
                }
              } else measure();
            },
            { root: container, threshold: 0 },
          )
        : null;
    observer?.observe(el);
    if (!observer && trigger === "enter") {
      entered = true;
      entryTime = performance.now();
    }
    const resize = typeof ResizeObserver !== "undefined" ? new ResizeObserver(measure) : null;
    resize?.observe(el);
    if (container) resize?.observe(container);
    if (target !== el) resize?.observe(target);
    const visibility = () => {
      if (document.hidden) {
        cancelAnimationFrame(frame);
        frame = 0;
        velocity = 0;
      } else measure();
    };
    (container ?? window).addEventListener("scroll", measure, { passive: true });
    window.addEventListener("resize", measure);
    media.addEventListener("change", measure);
    document.addEventListener("visibilitychange", visibility);
    measure();
    return () => {
      disposed = true;
      refresh.current = null;
      cancelAnimationFrame(frame);
      observer?.disconnect();
      resize?.disconnect();
      (container ?? window).removeEventListener("scroll", measure);
      window.removeEventListener("resize", measure);
      media.removeEventListener("change", measure);
      document.removeEventListener("visibilitychange", visibility);
    };
  }, [
    root,
    scrollContainer,
    scrollTarget,
    range?.[0],
    range?.[1],
    start,
    end,
    scrub,
    trigger,
    duration,
    delay,
    once,
    replayKey,
    key,
    preserveProgress,
    pageProgress,
  ]);
  useEffect(() => {
    refresh.current?.();
  }, [options.progress]);
}
export const scrollUnits = (el: HTMLElement) =>
  Array.from(el.querySelectorAll<HTMLElement>("[data-scroll-unit]")).filter(
    (unit) => unit.closest("[data-scroll-animation]") === el,
  );
export const scrollStage: CSSProperties = {
  position: "relative",
  width: "100%",
  height: "100%",
  minHeight: 240,
  overflow: "hidden",
};
